# ------------------------------------------------------------
# Load embedded empirical policy
# ------------------------------------------------------------

def _qt_load_model():

    payload = _QT_MODEL_DATA

    tables = {}

    for state in payload["states"]:

        (
            round_no,
            te_mine,
            te_theirs,
            is_maker,
            powers_mine,
            powers_theirs,
            turn,
            quote_bid,
            quote_ask,
            n_buy,
            n_sell,
            n_counter,
        ) = state

        key = (
            int(round_no),

            int(te_mine),

            int(te_theirs),

            bool(
                is_maker
            ),

            tuple(
                sorted(
                    str(x)
                    for x in powers_mine
                )
            ),

            tuple(
                sorted(
                    str(x)
                    for x in powers_theirs
                )
            ),

            int(turn),

            (
                None
                if quote_bid is None
                else int(quote_bid),

                None
                if quote_ask is None
                else int(quote_ask),
            ),
        )

        tables[key] = (
            int(n_buy),
            int(n_sell),
            int(n_counter),
        )

    global_counts = tuple(
        int(x)
        for x in payload["global"]
    )

    return (
        tables,
        global_counts,
    )


_QT_TABLES, _QT_GLOBAL = (
    _qt_load_model()
)


# ------------------------------------------------------------
# Exact Phase-4C key
# ------------------------------------------------------------

def _qt_state_key(
    *,
    round_no,
    te_mine,
    te_theirs,
    is_maker,
    powers_mine,
    powers_theirs,
    turn,
    quote,
):

    if quote is None:

        q = (
            None,
            None,
        )

    else:

        q = (
            int(
                quote[0]
            ),

            int(
                quote[1]
            ),
        )

    return (
        int(round_no),

        int(te_mine),

        int(te_theirs),

        bool(
            is_maker
        ),

        tuple(
            sorted(
                str(x)
                for x in powers_mine
            )
        ),

        tuple(
            sorted(
                str(x)
                for x in powers_theirs
            )
        ),

        int(turn),

        q,
    )


# ------------------------------------------------------------
# Probability prediction
# ------------------------------------------------------------

def _qt_predict(
    *,
    round_no,
    te_mine,
    te_theirs,
    is_maker,
    powers_mine,
    powers_theirs,
    turn,
    quote,
    smoothing=1.0,
):

    key = _qt_state_key(
        round_no=round_no,
        te_mine=te_mine,
        te_theirs=te_theirs,
        is_maker=is_maker,
        powers_mine=powers_mine,
        powers_theirs=powers_theirs,
        turn=turn,
        quote=quote,
    )

    counts = _QT_TABLES.get(
        key
    )

    if counts is None:

        counts = _QT_GLOBAL

    total = sum(
        counts
    )

    denominator = (
        total
        + smoothing * 3.0
    )

    return {
        "ACCEPT_BUY":
            (
                counts[0]
                + smoothing
            )
            / denominator,

        "ACCEPT_SELL":
            (
                counts[1]
                + smoothing
            )
            / denominator,

        "COUNTER":
            (
                counts[2]
                + smoothing
            )
            / denominator,
    }


# ------------------------------------------------------------
# State availability
# ------------------------------------------------------------

def _qt_known_state(
    *,
    round_no,
    te_mine,
    te_theirs,
    is_maker,
    powers_mine,
    powers_theirs,
    turn,
    quote,
):

    key = _qt_state_key(
        round_no=round_no,
        te_mine=te_mine,
        te_theirs=te_theirs,
        is_maker=is_maker,
        powers_mine=powers_mine,
        powers_theirs=powers_theirs,
        turn=turn,
        quote=quote,
    )

    return (
        key
        in _QT_TABLES
    )


# ------------------------------------------------------------
# Exact value
# ------------------------------------------------------------

def _qt_posterior_mean(
    self,
    obs,
):

    """
    Use the existing AdaptiveFinal valuation.

    We intentionally avoid creating a second valuation model.
    """

    try:

        return float(
            self._exact_value(
                obs
            )
        )

    except Exception:

        value = float(
            obs.k_mine
        )

        if hasattr(
            obs,
            "foresight",
        ):

            try:

                value += float(
                    sum(
                        obs.foresight
                    )
                )

            except Exception:

                pass

        return value


# ------------------------------------------------------------
# Legal counter enumeration
# ------------------------------------------------------------

def _qt_enumerate_counters(
    *,
    bid,
    ask,
    final_cap,
    min_reduction,
):

    if bid > ask:

        bid, ask = (
            ask,
            bid,
        )

    current_width = (
        ask - bid
    )

    max_width = min(
        current_width,

        max(
            final_cap,

            current_width
            - min_reduction,
        ),
    )

    counters = []

    for new_bid in range(
        bid,
        ask + 1,
    ):

        for new_ask in range(
            new_bid,
            ask + 1,
        ):

            width = (
                new_ask
                - new_bid
            )

            if width > max_width:
                continue

            counters.append(
                (
                    "COUNTER",
                    new_bid,
                    new_ask,
                )
            )

    counters.sort(
        key=lambda action: (
            action[2]
            - action[1],

            (
                action[1]
                + action[2]
            )
            / 2.0,

            action[1],

            action[2],
        )
    )

    return counters


# ------------------------------------------------------------
# Direct EV
# ------------------------------------------------------------

def _qt_accept_buy_ev(
    mean,
    ask,
):

    return (
        mean
        - ask
    )


def _qt_accept_sell_ev(
    mean,
    bid,
):

    return (
        bid
        - mean
    )


